args.sql:
with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' status, payload->>'project' proj, type
 from events where type in ('issue.created','issue.status_changed') and recorded_at <= TIMESTAMP '2020-02-12 17:13' and occurred_at <= TIMESTAMP '2020-02-11 18:18'
), dedup as (
 select *, row_number() over (partition by issue_key, type, occurred_at order by recorded_at desc, id) rn from (select e.*, ev.status, ev.proj from events e join ev using(id)) 
), cur as (
 select issue_key, status, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) r2 from dedup where rn=1
)
select count(*) from cur where r2=1 and status='Won''t Fix'

with ev as (
 select id, issue_key, type, occurred_at, recorded_at, payload->>'status' status
 from events where type in ('issue.created','issue.status_changed') and recorded_at <= TIMESTAMP '2020-02-12 17:13' and occurred_at <= TIMESTAMP '2020-02-11 18:18'
), dedup as (
 select *, row_number() over (partition by issue_key, type, occurred_at order by recorded_at desc, id desc) rn from ev
), cur as (
 select issue_key, status, row_number() over (partition by issue_key order by occurred_at desc, (type='issue.status_changed') desc, recorded_at desc) r2 from dedup where rn=1
)
select count(*) from cur where r2=1 and status='Won''t Fix'

with ev as (
 select * from events where recorded_at <= TIMESTAMP '2019-02-19 10:00' and occurred_at <= TIMESTAMP '2019-02-18 17:50'
 and type in ('issue.created','issue.status_changed')
), dedup as (
 select *, row_number() over (partition by issue_key, type, occurred_at order by recorded_at desc, id desc) rn from ev
), cur as (
 select issue_key, payload->>'status' status, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) r2 from dedup where rn=1
)
select status, count(*) from cur where r2=1 group by status order by 2 desc

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st, 0 ord from events where type='issue.created' and payload->>'project'='MXS'
 union all
 select issue_key, occurred_at, recorded_at, payload->>'status', 1 from events where type='issue.status_changed'
), v as (
 select * from ev where occurred_at <= TIMESTAMP '2018-10-30 14:46' and recorded_at <= TIMESTAMP '2018-10-31 07:25'
), dedup as (
 select *, row_number() over (partition by issue_key, occurred_at, ord order by recorded_at desc) rn from v
), last as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, ord desc, recorded_at desc) r2 from dedup where rn=1
)
select st, count(*) from last where r2=1 group by st order by 2 desc

select distinct payload->>'project' from events where type='issue.created';
select count(*) from events where type='issue.status_changed' and issue_key not in (select issue_key from events where type='issue.created');
select * from events where type='issue.status_changed' and occurred_at between TIMESTAMP '2018-06-04 00:00' and TIMESTAMP '2018-06-05 00:00' and (payload->>'status'='In Review' or issue_key in (select issue_key from events where type='issue.status_changed' and payload->>'status'='In Review' and occurred_at between TIMESTAMP '2018-05-01' and TIMESTAMP '2018-06-10')) order by issue_key, occurred_at

with ev as (
  select issue_key, occurred_at, recorded_at, payload->>'status' s, type, id from events
  where type in ('issue.status_changed','issue.created')
    and recorded_at <= TIMESTAMP '2018-01-01 17:21' and occurred_at <= TIMESTAMP '2017-12-27 14:31'
), dedup as (
  select * from ev qualify row_number() over (partition by issue_key, type, occurred_at order by recorded_at desc, id desc)=1
), cur as (
  select * from dedup qualify row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc, id desc)=1
)
select count(*) from cur where s='Stalled'

with ev as (
 select issue_key, occurred_at, recorded_at, id, payload->>'status' st, type from events
 where type in ('issue.created','issue.status_changed') and occurred_at <= TIMESTAMP '2018-09-10 20:48' and recorded_at <= TIMESTAMP '2018-09-30 23:35'
), dedup as (
 select * from ev qualify row_number() over (partition by issue_key, type, occurred_at order by recorded_at desc, id desc)=1
), cur as (
 select * from dedup qualify row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc, id desc)=1
)
select st, count(*) from cur group by 1 order by 2 desc

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st, 0 pri from events where type='issue.created' and payload->>'project'='MXS'
 union all
 select issue_key, occurred_at, recorded_at, payload->>'status', 1 from events where type='issue.status_changed'
), f as (
 select * from ev where occurred_at<=TIMESTAMP '2017-03-11 08:52' and recorded_at<=TIMESTAMP '2017-03-13 10:29'
), r as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc, pri desc) rn from f
)
select st, count(*) from r where rn=1 group by st order by 2 desc

with ev as (
  select issue_key, occurred_at, recorded_at, payload->>'status' as status from events where type in ('issue.created','issue.status_changed')
),
dedup as (
  select * from (select *, row_number() over (partition by issue_key, occurred_at order by recorded_at desc) rn from ev) where rn=1
),
st as (
  select issue_key, status, row_number() over (partition by issue_key order by occurred_at desc) r from dedup where occurred_at <= TIMESTAMP '2017-08-12 00:39'
),
st2 as (
  select issue_key, status, row_number() over (partition by issue_key order by occurred_at desc) r from dedup where occurred_at <= TIMESTAMP '2017-10-11 02:44'
)
select a.issue_key, a.status, b.status from st a join st2 b using(issue_key) where a.r=1 and b.r=1 and a.status in ('Confirmed','In Progress','In Review','Stalled') and b.status in ('Confirmed','In Progress','In Review','Stalled') order by 1

with ev as (
  select issue_key, occurred_at, recorded_at, payload->>'status' as status, type from events
  where type in ('issue.created','issue.status_changed')
   and occurred_at <= TIMESTAMP '2015-02-25 11:09' and recorded_at <= TIMESTAMP '2015-03-19 02:27'
), proj as (
  select issue_key from events where type='issue.created' and payload->>'project'='SEC'
), ranked as (
  select ev.*, row_number() over (partition by ev.issue_key order by occurred_at desc, recorded_at desc, case when type='issue.created' then 0 else 1 end desc) rn
  from ev join proj using(issue_key)
)
select status, count(*) from ranked where rn=1 group by status order by 2 desc

with ev as (
 select * from events where recorded_at <= TIMESTAMP '2008-05-09 09:40' and occurred_at <= TIMESTAMP '2008-05-09 07:21'
 and type in ('issue.created','issue.status_changed')
), dedup as (
 select *, row_number() over (partition by issue_key, type, occurred_at order by recorded_at desc, id desc) rn from ev
), last as (
 select issue_key, payload->>'status' status, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc, id desc) r2
 from dedup where rn=1
)
select status, count(*) from last where r2=1 group by 1

with c as (
 select issue_key, occurred_at, payload->>'status' s, recorded_at from events where type='issue.created' and payload->>'project'='SEC'
 union all
 select issue_key, occurred_at, payload->>'status', recorded_at from events where type='issue.status_changed' and issue_key in (select issue_key from events where type='issue.created' and payload->>'project'='SEC')
), d as (
 select *, row_number() over (partition by issue_key, occurred_at order by recorded_at desc) rn from c
), st as (
 select issue_key, s, occurred_at, row_number() over (partition by issue_key order by occurred_at desc) r from d where rn=1 and occurred_at<=TIMESTAMP '2005-08-15 12:19'
), st2 as (
 select issue_key, s, occurred_at, row_number() over (partition by issue_key order by occurred_at desc) r from d where rn=1 and occurred_at<=TIMESTAMP '2005-10-23 13:20'
)
select a.issue_key, a.s, b.s from st a join st2 b using(issue_key) where a.r=1 and b.r=1 and a.s in ('In Progress','Investigating','Waiting for Feedback') and b.s in ('In Progress','Investigating','Waiting for Feedback')

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' s, type from events where type in ('issue.created','issue.status_changed') and payload->>'status' is not null
), dedup as (
 select * from ev qualify row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc)=1
), st as (
 select issue_key, s from (select *, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) rn from dedup where occurred_at <= TIMESTAMP '2006-04-02 09:56') where rn=1
), st2 as (
 select issue_key, s from (select *, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) rn from dedup where occurred_at <= TIMESTAMP '2006-05-20 17:32') where rn=1
)
select st.issue_key, st.s, st2.s from st join st2 using(issue_key) where st.s in ('In Progress','Investigating','Waiting for Feedback') and st2.s in ('In Progress','Investigating','Waiting for Feedback')

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st from events where type='issue.status_changed'
 union all
 select issue_key, occurred_at, recorded_at, payload->>'status' from events where type='issue.created' and payload->>'project'='SEC'
), d as (
 select *, row_number() over (partition by issue_key, occurred_at order by recorded_at desc) rn from ev
), l as (
 select issue_key, occurred_at, st from d where rn=1
), s1 as (
 select issue_key, arg_max(st, occurred_at) st from l where occurred_at<=TIMESTAMP '2013-12-10 02:01' group by issue_key
), s2 as (
 select issue_key, arg_max(st, occurred_at) st from l where occurred_at<=TIMESTAMP '2014-03-01 17:32' group by issue_key
)
select s1.issue_key, s1.st, s2.st from s1 join s2 using(issue_key)
where s1.st in ('In Progress','Investigating','Waiting for Feedback') and s2.st in ('In Progress','Investigating','Waiting for Feedback')
order by 1

with d as (
 select case when src='AC-1866' then dst else src end as k from links_at(TIMESTAMP '2020-01-24 20:50') where relation='duplicates' and (src='AC-1866' or dst='AC-1866')
)
select distinct d.k as dup, case when l.src=d.k then l.dst else l.src end as rel
from d join links_at(TIMESTAMP '2020-01-24 20:50') l on l.relation='relates_to' and (l.src=d.k or l.dst=d.k)
order by 1,2

with d as (
 select case when src='AC-2202' then dst else src end as k from links_at(TIMESTAMP '2020-06-15 19:20') where relation='duplicates' and (src='AC-2202' or dst='AC-2202')
)
select distinct d.k as dup, case when l.src=d.k then l.dst else l.src end as rel
from d join links_at(TIMESTAMP '2020-06-15 19:20') l on l.relation='relates_to' and (l.src=d.k or l.dst=d.k)
order by 1,2

with d as (
select case when src='GRBK-584' then dst else src end as k from links_at(TIMESTAMP '2014-03-18 19:42') where relation='duplicates' and (src='GRBK-584' or dst='GRBK-584')
)
select distinct d.k as dup, case when l.src=d.k then l.dst else l.src end as rel
from d join links_at(TIMESTAMP '2014-03-18 19:42') l on l.relation='relates_to' and (l.src=d.k or l.dst=d.k)
order by 1,2

with t as (select TIMESTAMP '2013-08-30 19:34' t),
dep as (
 select distinct case when src='GRBK-752' then dst else src end k
 from links_at(TIMESTAMP '2013-08-30 19:34')
 where relation='depends_on' and (src='GRBK-752' or dst='GRBK-752')
)
select d.k, case when l.src=d.k then l.dst else l.src end other, l.relation
from dep d join links_at(TIMESTAMP '2013-08-30 19:34') l on l.relation='duplicates' and (l.src=d.k or l.dst=d.k)

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st, 0 src from events where type='issue.created' and payload->>'project'='AC'
 union all
 select issue_key, occurred_at, recorded_at, payload->>'status', 1 from events where type='issue.status_changed'
), v as (
 select * from ev where occurred_at<=TIMESTAMP '2017-05-26 17:27' and recorded_at<=TIMESTAMP '2017-05-27 00:02'
), dedup as (
 select *, row_number() over (partition by issue_key, occurred_at, src order by recorded_at desc) rn from v
), last as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, src desc, recorded_at desc) r2 from dedup where rn=1
)
select st, count(*) from last where r2=1 group by st order by 2 desc

with ev as (
  select issue_key, occurred_at, payload->>'status' s, recorded_at from events where type='issue.status_changed'
  union all
  select issue_key, occurred_at, payload->>'status', recorded_at from events where type='issue.created'
), dedup as (
  select * from (select *, row_number() over (partition by issue_key, occurred_at order by recorded_at desc) rn from ev) where rn=1
), st as (
  select issue_key, ts, (select s from dedup d where d.issue_key=k.issue_key and d.occurred_at<=ts order by occurred_at desc limit 1) s
  from (select distinct issue_key from dedup) k, (values (TIMESTAMP '2018-04-11 08:47'),(TIMESTAMP '2018-04-25 12:04')) t(ts)
)
select issue_key from st group by issue_key
having sum(case when s in ('In Progress','Under Review') then 1 else 0 end)=2 order by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' s from events where type='issue.created' and payload->>'project'='GRBK'
 union all
 select issue_key, occurred_at, recorded_at, payload->>'status' from events where type='issue.status_changed'
), f as (
 select * from ev where occurred_at <= TIMESTAMP '2012-04-23 17:48' and recorded_at <= TIMESTAMP '2012-04-27 04:43'
), r as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) rn from f
)
select s, count(*) from r where rn=1 group by s

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st, type from events
 where type in ('issue.created','issue.status_changed') and recorded_at <= TIMESTAMP '2011-06-17 04:17' and occurred_at <= TIMESTAMP '2011-06-16 22:03'
), dedup as (
 select *, row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc, ) rn from ev
), last as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, case when type='issue.status_changed' then 1 else 0 end desc) r2 from dedup where rn=1
)
select st, count(*) from last where r2=1 group by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st, 1 as k from events where type='issue.created'
 union all
 select issue_key, occurred_at, recorded_at, payload->>'status', 2 from events where type='issue.status_changed'
), v as (
 select * from ev where occurred_at <= TIMESTAMP '2009-08-25 20:29' and recorded_at <= TIMESTAMP '2009-09-14 07:32'
), dedup as (
 select *, row_number() over (partition by issue_key, occurred_at, k order by recorded_at desc) rn from v
), d2 as (select * from dedup where rn=1),
latest as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, k desc) r from d2
)
select st, count(*) from latest where r=1 group by st order by 2 desc

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' s, type from events
 where type in ('issue.created','issue.status_changed') and occurred_at <= TIMESTAMP '2011-04-14 00:49' and recorded_at <= TIMESTAMP '2011-04-14 19:11'
 and (type='issue.status_changed' or payload->>'project'='GRBK')
), dedup as (
 select *, row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc, id) rn from (select e.*, ev.s as s2 from ev join events e using(issue_key, occurred_at, recorded_at, type)) 
), cur as (
 select issue_key, s, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) r from ev
)
select s, count(*) from cur where r=1 group by s

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st, type from events where type in ('issue.created','issue.status_changed')
), dedup as (
 select *, row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc) rn from ev
), cur as (select * from dedup where rn=1),
st as (
 select issue_key, ts, (select st from cur c where c.issue_key=i.issue_key and c.occurred_at<=ts order by occurred_at desc, (type='issue.status_changed') desc limit 1) s
 from (select distinct issue_key from cur) i, (values (TIMESTAMP '2012-03-18 07:10'),(TIMESTAMP '2012-06-13 19:13')) t(ts)
)
select issue_key from st group by issue_key having count(*) filter (where s='In Progress')=2 order by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' s, id,
  row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc, id desc) rn
 from events where type in ('issue.status_changed','issue.created')
),
cur as (select * from ev where rn=1),
st as (
 select issue_key, t, (select s from cur where cur.issue_key=k.issue_key and occurred_at<=t order by occurred_at desc limit 1) s
 from (select distinct issue_key from cur) k, (values (TIMESTAMP '2011-08-29 23:37'),(TIMESTAMP '2011-09-14 02:46')) v(t)
)
select issue_key from st group by issue_key having sum(case when s='In Progress' then 1 else 0 end)=2 order by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' s, type from events where type in ('issue.status_changed','issue.created')
), dedup as (
 select * from ev qualify row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc)=1
), st as (
 select issue_key, s, occurred_at, row_number() over (partition by issue_key order by occurred_at desc, case when type='issue.created' then 0 else 1 end desc) rn from dedup where occurred_at <= TIMESTAMP '2011-10-06 19:56'
), st2 as (
 select issue_key, s, occurred_at, row_number() over (partition by issue_key order by occurred_at desc, case when type='issue.created' then 0 else 1 end desc) rn from dedup where occurred_at <= TIMESTAMP '2011-12-30 03:32'
)
select a.issue_key from st a join st2 b using(issue_key) where a.rn=1 and b.rn=1 and a.s='In Progress' and b.s='In Progress' order by 1

with ev as (
 select issue_key, occurred_at, payload->>'status' s, recorded_at, type from events where type in ('issue.created','issue.status_changed')
), dedup as (
 select * from ev qualify row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc)=1
), st as (
 select issue_key, s, occurred_at, row_number() over (partition by issue_key order by occurred_at desc, case when type='issue.created' then 0 else 1 end) rn from dedup where occurred_at <= TIMESTAMP '2011-08-30 20:01'
), st2 as (
 select issue_key, s, occurred_at, row_number() over (partition by issue_key order by occurred_at desc, case when type='issue.created' then 0 else 1 end) rn from dedup where occurred_at <= TIMESTAMP '2011-11-06 21:28'
)
select a.issue_key from (select * from st where rn=1 and s='In Progress') a join (select * from st2 where rn=1 and s='In Progress') b using(issue_key) order by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st, type from events
 where type in ('issue.created','issue.status_changed') and recorded_at <= TIMESTAMP '2021-02-08 20:44' and occurred_at <= TIMESTAMP '2021-02-04 12:48'
), dedup as (
 select *, row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc) rn from ev
), last as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, case when type='issue.created' then 0 else 1 end desc, recorded_at desc) r2 from dedup where rn=1
)
select st, count(*) from last where r2=1 group by st order by 2 desc

with ev as (
  select issue_key, occurred_at, recorded_at, coalesce(payload->>'status') st, type
  from events where type in ('issue.created','issue.status_changed')
), dedup as (
  select * from ev qualify row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc)=1
), at_t as (
  select issue_key, st, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) rn, 1 t from dedup where occurred_at <= TIMESTAMP '2021-07-03 22:34'
), at_u as (
  select issue_key, st, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) rn from dedup where occurred_at <= TIMESTAMP '2021-09-12 11:39'
)
select a.issue_key, a.st, b.st from at_t a join at_u b using(issue_key)
where a.rn=1 and b.rn=1 and a.st in ('Coding In Progress','In Progress','Pull Request Sent') and b.st in ('Coding In Progress','In Progress','Pull Request Sent')
order by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' s from events where type in ('issue.created','issue.status_changed')
), dedup as (
 select * from ev qualify row_number() over (partition by issue_key, occurred_at order by recorded_at desc)=1
), st as (
 select issue_key, s, row_number() over (partition by issue_key order by occurred_at desc) rn from dedup where occurred_at<=TIMESTAMP '2021-04-16 09:03'
), st2 as (
 select issue_key, s, row_number() over (partition by issue_key order by occurred_at desc) rn from dedup where occurred_at<=TIMESTAMP '2021-05-29 21:22'
)
select a.issue_key, a.s, b.s from st a join st2 b using(issue_key) where a.rn=1 and b.rn=1 and a.s in ('Coding In Progress','In Progress','Pull Request Sent') and b.s in ('Coding In Progress','In Progress','Pull Request Sent') order by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' s from events where type in ('issue.status_changed','issue.created')
),
dedup as (
 select *, row_number() over (partition by issue_key, occurred_at order by recorded_at desc) rn from ev
),
d as (select * from dedup where rn=1),
st as (
 select k, (select s from d where d.issue_key=k and occurred_at<=TIMESTAMP '2020-12-06 07:17' order by occurred_at desc limit 1) s1,
 (select s from d where d.issue_key=k and occurred_at<=TIMESTAMP '2021-01-30 16:46' order by occurred_at desc limit 1) s2
 from (select distinct issue_key k from d)
)
select k, s1, s2 from st where s1 in ('Coding In Progress','In Progress','Pull Request Sent') and s2 in ('Coding In Progress','In Progress','Pull Request Sent') order by k

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st, type from events
 where type in ('issue.created','issue.status_changed') and occurred_at <= TIMESTAMP '2014-10-01 11:34' and recorded_at <= TIMESTAMP '2014-10-05 12:33'
 and (type='issue.status_changed' or payload->>'project'='TAJO')
), dedup as (
 select *, row_number() over (partition by issue_key, type, occurred_at order by recorded_at desc) rn from ev
), cur as (
 select issue_key, st, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) r from dedup where rn=1
)
select count(*), count(distinct issue_key) from cur where r=1 and st='Open'

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' s, id from events
 where type in ('issue.created','issue.status_changed') and occurred_at <= TIMESTAMP '2016-01-06 18:17' and recorded_at <= TIMESTAMP '2016-01-06 20:30'
 and (type='issue.status_changed' or payload->>'project'='TAJO' or true)
), dedup as (
 select *, row_number() over (partition by issue_key, occurred_at order by recorded_at desc, id desc) rn from ev
), cur as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) r2 from dedup where rn=1
)
select s, count(*) from cur where r2=1 group by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' s, 1 as pri from events where type='issue.created' and recorded_at<=TIMESTAMP '2014-09-29 12:25' and occurred_at<=TIMESTAMP '2014-09-29 03:10'
 union all
 select issue_key, occurred_at, recorded_at, payload->>'status', 2 from events where type='issue.status_changed' and recorded_at<=TIMESTAMP '2014-09-29 12:25' and occurred_at<=TIMESTAMP '2014-09-29 03:10'
), dedup as (
 select *, row_number() over (partition by issue_key, occurred_at, pri order by recorded_at desc) rn from ev
), cur as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, pri desc) r2 from dedup where rn=1
)
select s, count(*) from cur where r2=1 group by s

with e as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st, type from events
 where type in ('issue.created','issue.status_changed') and occurred_at <= TIMESTAMP '2013-12-24 08:54' and recorded_at <= TIMESTAMP '2013-12-27 07:11'
 and (type='issue.status_changed' or payload->>'project'='TAJO' or true)
), d as (
 select *, row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc) rn from e
), l as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, (type='issue.status_changed') desc) r2 from d where rn=1
)
select st, count(*) from l where r2=1 group by 1

with ev as (
  select issue_key, occurred_at, payload->>'status' status, recorded_at,
    row_number() over (partition by issue_key, type, occurred_at order by recorded_at desc, id desc) rn
  from events where type in ('issue.created','issue.status_changed')
), cur as (select * from ev where rn=1),
st as (
  select k, (select status from cur where issue_key=k and occurred_at<=t order by occurred_at desc limit 1) s
  from (select distinct issue_key k from cur) , (select TIMESTAMP '2013-05-15 05:39' t union all select TIMESTAMP '2013-07-10 23:58') 
)
select k from st group by k having 
 count(*) filter (where s in ('In Progress','Patch Available'))=2 order by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' s from events where type in ('issue.created','issue.status_changed')
),
dedup as (
 select * from (select *, row_number() over (partition by issue_key, occurred_at order by recorded_at desc) rn from ev) where rn=1
),
st as (
 select issue_key, ts, (select s from dedup d where d.issue_key=i.issue_key and d.occurred_at<=ts order by occurred_at desc limit 1) s
 from (select distinct issue_key from dedup) i, (values (TIMESTAMP '2013-11-03 01:17'),(TIMESTAMP '2014-01-21 15:38')) t(ts)
)
select issue_key from st group by issue_key
having sum(case when s in ('In Progress','Patch Available') then 1 else 0 end)=2
order by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' as status, 1 as src from events where type='issue.status_changed'
 union all
 select issue_key, occurred_at, recorded_at, payload->>'status', 0 from events where type='issue.created'
), f as (
 select * from ev where recorded_at <= TIMESTAMP '2012-07-31 16:19' and occurred_at <= TIMESTAMP '2012-07-31 05:03'
), r as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc, src desc) rn from f
)
select status, count(*) from r where rn=1 group by status order by 2 desc

with ev as (
 select issue_key, occurred_at, recorded_at, id, payload->>'status' s from events
 where type in ('issue.created','issue.status_changed') and occurred_at <= TIMESTAMP '2015-01-29 16:23' and recorded_at <= TIMESTAMP '2015-01-29 18:23'
), dedup as (
 select *, row_number() over (partition by issue_key, occurred_at, (case when 1=1 then 1 end) order by recorded_at desc, id desc) rn from ev
), latest as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc, id desc) r from dedup where rn=1
)
select s, count(*) from latest where r=1 group by s

with ev as (
  select issue_key, occurred_at, recorded_at, id, payload->>'status' s, 'c' k from events where type='issue.created'
  union all
  select issue_key, occurred_at, recorded_at, id, payload->>'status', 's' from events where type='issue.status_changed'
), v as (
  select * from ev where recorded_at <= TIMESTAMP '2012-02-25 23:55' and occurred_at <= TIMESTAMP '2012-02-24 10:16'
), dedup as (
  select *, row_number() over (partition by issue_key, occurred_at, k order by recorded_at desc, id desc) rn from v
), d as (select * from dedup where rn=1),
last as (
  select *, row_number() over (partition by issue_key order by occurred_at desc, (k='s') desc, recorded_at desc) r2 from d
)
select s, count(*) from last where r2=1 group by s

with ev as (
  select issue_key, occurred_at, recorded_at, payload->>'status' st, 1 k from events where type='issue.created' and payload->>'project'='RAVE'
  union all
  select issue_key, occurred_at, recorded_at, payload->>'status', 2 from events where type='issue.status_changed'
), v as (
  select * from ev where recorded_at <= TIMESTAMP '2012-01-06 05:13' and occurred_at <= TIMESTAMP '2012-01-06 01:41'
), ranked as (
  select *, row_number() over (partition by issue_key order by occurred_at desc, k desc, recorded_at desc) rn from v
)
select st, count(*) from ranked where rn=1 group by st

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st, type from events
 where type in ('issue.created','issue.status_changed') and recorded_at <= TIMESTAMP '2012-05-06 02:40' and occurred_at <= TIMESTAMP '2012-05-03 23:09'
), dedup as (
 select * from ev qualify row_number() over (partition by issue_key, type, occurred_at order by recorded_at desc)=1
), last as (
 select * from dedup qualify row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc)=1
)
select st, count(*) from last group by st

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' as status, 1 as src from events where type='issue.created' and payload->>'project'='RAVE'
 union all
 select issue_key, occurred_at, recorded_at, payload->>'status', 2 from events where type='issue.status_changed'
), v as (
 select * from ev where occurred_at <= TIMESTAMP '2013-02-14 15:49' and recorded_at <= TIMESTAMP '2013-02-17 17:57'
), r as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, src desc, recorded_at desc) rn from v
)
select status, count(*) from r where rn=1 group by status order by 2 desc

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st, type from events where type in ('issue.created','issue.status_changed') and issue_key like 'RAVE-%'
), dedup as (
 select * from ev qualify row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc)=1
), at1 as (
 select issue_key, st from dedup where occurred_at<=TIMESTAMP '2012-05-03 17:42' qualify row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc)=1
), at2 as (
 select issue_key, st from dedup where occurred_at<=TIMESTAMP '2012-06-17 04:42' qualify row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc)=1
)
select a.issue_key from at1 a join at2 b using(issue_key) where a.st='In Progress' and b.st='In Progress' order by 1

with ev as (
  select issue_key, occurred_at, recorded_at, payload->>'status' s from events where type in ('issue.status_changed','issue.created')
), latest as (
  select * from (select *, row_number() over (partition by issue_key, occurred_at order by recorded_at desc) rn from ev) where rn=1
), at1 as (
  select issue_key, s from (select *, row_number() over (partition by issue_key order by occurred_at desc) r from latest where occurred_at <= TIMESTAMP '2012-05-06 08:17') where r=1
), at2 as (
  select issue_key, s from (select *, row_number() over (partition by issue_key order by occurred_at desc) r from latest where occurred_at <= TIMESTAMP '2012-07-15 21:37') where r=1
)
select a.issue_key from at1 a join at2 b using(issue_key) where a.s='In Progress' and b.s='In Progress' order by 1

with ev as (
  select issue_key, occurred_at, recorded_at, payload->>'status' st, type from events where type in ('issue.created','issue.status_changed')
), dedup as (
  select * from ev qualify row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc)=1
), at1 as (
  select issue_key, st from dedup where occurred_at<=TIMESTAMP '2012-09-17 04:51' qualify row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc)=1
), at2 as (
  select issue_key, st from dedup where occurred_at<=TIMESTAMP '2012-11-08 05:34' qualify row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc)=1
)
select a.issue_key from at1 a join at2 b using(issue_key) where a.st='In Progress' and b.st='In Progress' order by 1

with ev as (
  select issue_key, occurred_at, recorded_at, payload->>'status' s from events where type in ('issue.created','issue.status_changed')
),
latest as (
  select *, row_number() over (partition by issue_key, occurred_at order by recorded_at desc) rn from ev
),
st as (
  select issue_key, occurred_at, s from latest where rn=1
),
at1 as (
  select issue_key, s, row_number() over (partition by issue_key order by occurred_at desc) r from st where occurred_at <= TIMESTAMP '2012-08-13 08:59'
),
at2 as (
  select issue_key, s, row_number() over (partition by issue_key order by occurred_at desc) r from st where occurred_at <= TIMESTAMP '2012-11-07 22:17'
)
select a.issue_key from at1 a join at2 b using(issue_key) where a.r=1 and b.r=1 and a.s='In Progress' and b.s='In Progress' order by 1

with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' status, type
 from events where type in ('issue.created','issue.status_changed') and payload->>'project' is not distinct from payload->>'project'
),
dedup as (
 select * from ev qualify row_number() over (partition by issue_key, occurred_at, type order by recorded_at desc)=1
),
st as (
 select issue_key, t, (select status from dedup d where d.issue_key=k.issue_key and d.occurred_at<=t order by occurred_at desc, recorded_at desc limit 1) status
 from (select distinct issue_key from dedup) k, (values (TIMESTAMP '2012-06-12 14:08'),(TIMESTAMP '2012-07-27 11:25')) v(t)
)
select issue_key from st where status='In Progress' group by issue_key having count(*)=2 order by 1
